import { StudyUnit, VocabEntry } from '../../types/curriculum';

function v(
  unitNumber: number,
  unitTitle: string,
  idx: number,
  category: VocabEntry['category'],
  term: string,
  partOfSpeech: string,
  definition: string,
  vietnamese: string,
  example: string
): VocabEntry {
  return {
    id: `db1-u${unitNumber}-v${idx}`,
    unitNumber,
    unitTitle,
    category,
    term,
    partOfSpeech,
    definition,
    vietnamese,
    example,
  };
}

